:root {
  --clr-bg: #fff8f0;
  --clr-header: #e8421a;
  --clr-header-text: #ffffff;
  --clr-title: #1a1a1a;
  --clr-subtitle: #e8421a;
  --clr-label: #888888;
  --clr-value: #1a1a1a;
  --clr-divider: #e8421a;
  --clr-dot: #e8d5c4;
  --clr-badge-bg: #fff0e6;
  --clr-badge-text: #e8421a;
  --clr-badge-border: #e8421a;
  --clr-code: #aaaaaa;
  --clr-border: #f0d9c8;
}

.ticket {
  background: var(--clr-bg);
  border: 2px solid var(--clr-border);
  border-radius: 16px;
  width: 380px;
  padding: 0;
  overflow: hidden;
  font-size: 14px;
}

.ticket-header {
  background: var(--clr-header);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
}

.ticket-emoji {
  font-size: 32px;
  line-height: 1;
}

.ticket-title-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ticket-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--clr-header-text);
  margin: 0;
  line-height: 1.2;
}

.ticket-subtitle {
  font-size: 12px;
  font-weight: 400;
  color: var(--clr-header-text);
  margin: 0;
  opacity: 0.85;
}

.ticket-divider {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 0 0;
}

.divider-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--clr-dot);
  flex-shrink: 0;
}

.divider-line {
  flex: 1;
  height: 2px;
  border-top: 2px dashed var(--clr-divider);
}

.ticket-details {
  display: flex;
  justify-content: space-around;
  padding: 16px 20px;
  gap: 8px;
}

.detail-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.detail-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--clr-label);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.detail-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--clr-value);
}

.ticket-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 1px solid var(--clr-border);
}

.ticket-badge {
  font-size: 12px;
  font-weight: 600;
  color: var(--clr-badge-text);
  background: var(--clr-badge-bg);
  border: 1px solid var(--clr-badge-border);
  border-radius: 20px;
  padding: 4px 12px;
}

.ticket-code {
  font-size: 13px;
  font-weight: 700;
  color: var(--clr-code);
  letter-spacing: 0.05em;
}
